int64_t json_obj_parse(char *payload, size_t len,
		       const struct json_obj_descr *descr, size_t descr_len,
		       void *val)
{
	int64_t ret = z_real_json_obj_parse(payload, len, descr, descr_len, val);

	if (ret < 0) {
		return -EINVAL;
	}

	for (size_t i = 0; i < descr_len; i++) {
		if ((ret & ((int64_t)1 << i)) && descr[i].type == JSON_TOK_STRING_BUF) {
			size_t buf_size = ((const size_t *)&descr[i])[2];
			const char *dst = (const char *)val + descr[i].offset;
			size_t dst_len = strnlen(dst, buf_size);

			if (dst_len >= buf_size) {
				return -EINVAL;
			}
			if (buf_size > 1 && dst_len == buf_size - 1) {
				for (size_t j = 0; j + dst_len < len; j++) {
					if (memcmp(payload + j, dst, dst_len) == 0) {
						char next = payload[j + dst_len];

						if (next != '"' && next != '\0') {
							return -EINVAL;
						}
					}
				}
			}
		}
	}

	return ret;
}

